mapper.select:
SELECT id, region, flag_key, description, enabled, rollout_percent, created_at
FROM feature_flag
WHERE id=#{id} AND region=#{region}

SELECT id, region, flag_key, description, enabled, rollout_percent, created_at
FROM feature_flag
WHERE region=#{region} AND flag_key=#{flagKey}

SELECT id, region, name, flag_key, status, created_at
FROM experiment
WHERE id=#{id} AND region=#{region}

SELECT id, experiment_id, user_id, variant, created_at
FROM experiment_assignment
WHERE experiment_id=#{experimentId} AND user_id=#{userId}
